import collections
from typing import List

class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        if not words:
            return []
        wlen = len(words[0])
        n = wlen * len(words)
        occ = collections.Counter(words)
        res = []
        # slide window for each possible offset
        for offset in range(wlen):
            left = offset
            cnt = collections.Counter()
            for j in range(offset, len(s) - wlen + 1, wlen):
                word = s[j:j+wlen]
                if word not in occ:
                    cnt.clear()
                    left = j + wlen
                else:
                    cnt[word] += 1
                    while cnt[word] > occ[word]:
                        cnt[s[left:left+wlen]] -= 1
                        left += wlen
                    if j - left + wlen == n:
                        res.append(left)
        return res

