class Solution:
    def maxPower(self, stations: List[int], r: int, k: int) -> int:
        start, end = 0, sum(stations)
        while start + 1 < end:
            mid = (start + end) // 2
            if self.check(stations, r, k, mid):
                start = mid
            else:
                end = mid
        return end if self.check(stations, r, k, end) else start

    def check(self, stations, r, k, target):
        n = len(stations)
        arr = stations[:]  # work on a copy to avoid mutating the original list
        power = sum(arr[:r])
        for i in range(n):
            if i + r < n:
                power += arr[i + r]
            if i - r - 1 >= 0:
                power -= arr[i - r - 1]
            if power >= target:
                continue
            elif power + k < target:
                return False
            else:
                diff = target - power
                power = target
                idx = min(i + r, n - 1)
                arr[idx] += diff
                k -= diff
        return True

