class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD=10**9+7
        dp=[1]
        for c in s:
            nd=[0]*(len(dp)+1)
            if c=='D':
                acc=0
                for j in range(len(dp)-1,-1,-1):
                    acc+=dp[j]
                    nd[j]=acc
            else:
                acc=0
                for j in range(len(dp)):
                    acc+=dp[j]
                    nd[j+1]=acc
            dp=nd
        return sum(dp)%MOD

