class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        s1 = ''.join(c for c in s1 if c in set(s2))
        rec, track = [0], {}
        ct = start = i = 0
        n = 0
        while True:
            for ch in s2:
                i = s1.find(ch, start)
                if i == -1:
                    ct += 1
                    i = s1.find(ch)
                start = i + 1
            rec.append(ct + 1)
            if rec[-1] > n1:
                return (len(rec) - 2) // n2
            if i not in track:
                track[i] = len(rec) - 1
            else:
                break
        cycle_start = rec[track[i]]
        cycle_len = len(rec) - 1 - track[i]
        cycles = (n1 - track[i]) // cycle_len
        total = cycle_len * cycles + rec[-1] - cycle_start
        return total // n2

