class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        if not s1:
            return 0
        i = 0                     # current position in s2
        cnt_s2 = 0                # completed s2 repetitions
        start = {}                # (i%len(s2), cnt_s2) -> repeat number
        lens1, lens2 = len(s1), len(s2)

        for rep in range(n1):
            for ch in s1:
                if ch == s2[i % lens2]:
                    i += 1
                    if i % lens2 == 0:
                        cnt_s2 += 1
            state = (i % lens2, cnt_s2)
            if state in start:
                prev_rep, prev_cnt = start[state]
                cycle_len = rep - prev_rep
                cycle_cnt = cnt_s2 - prev_cnt
                cycles = (n1 - rep - 1) // cycle_len
                cnt_s2 += cycles * cycle_cnt
                # simulate the remaining repetitions
                for _ in range((n1 - rep - 1) % cycle_len):
                    for ch in s1:
                        if ch == s2[i % lens2]:
                            i += 1
                            if i % lens2 == 0:
                                cnt_s2 += 1
                break
            start[state] = (rep, cnt_s2)
        return cnt_s2 // n2

