class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        indegree = {}
        graph = defaultdict(list)
        n = len(recipes)

        for r in recipes:
            indegree[r] = 0

        for r, ing in zip(recipes, ingredients):
            for ing_item in ing:
                indegree.setdefault(ing_item, 0)
                graph[ing_item].append(r)
                indegree[r] += 1

        q = deque([i for i, deg in indegree.items() if deg == 0])
        possible = []
        ans = defaultdict(list)

        while q:
            node = q.popleft()
            if node in recipes:
                # check if all needed ingredients are in supplies
                if all(req in supplies for req in ingredients[recipes.index(node)]):
                    possible.append(node)
                    supplies.append(node)
            for nei in graph[node]:
                indegree[nei] -= 1
                if indegree[nei] == 0:
                    q.append(nei)

        return possible

