class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        dp = [1] * (n + 1)
        for ch in s:
            ndp = [0] * (len(dp) + 1)
            if ch == 'I':
                pref = 0
                for k in range(len(dp)):
                    pref = (pref + dp[k]) % MOD
                    ndp[k + 1] = pref
            else:  # 'D'
                suff = 0
                for k in range(len(dp) - 1, -1, -1):
                    suff = (suff + dp[k]) % MOD
                    ndp[k] = suff
            dp = ndp
        return dp[0] % MOD

