class Solution:
    def minFlips(self, a: int, b: int, c: int) -> int:
        cnt = 0
        while a or b or c:
            av, bv, cv = a & 1, b & 1, c & 1
            if cv == 0:
                cnt += av + bv          # flip 1s to 0
            else:
                cnt += 1 - (av | bv)    # flip if both are 0
            a >>= 1
            b >>= 1
            c >>= 1
        return cnt

