class Solution:
    def numPermsDISequence(self, s: str) -> int:
        from collections import defaultdict
        mem = {}
        MOD = 10**9 + 7

        def dfs(i, val):
            if i == len(s):
                return 1
            if (i, val) in mem:
                return mem[(i, val)]
            p = 0
            if s[i] == "D":
                for ind in range(val):
                    p = (p + dfs(i + 1, ind)) % MOD
            else:
                for ind in range(val + 1, i + 2):
                    p = (p + dfs(i + 1, ind)) % MOD
            mem[(i, val)] = p
            return p

        return dfs(0)

