class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        @cache
        def dp(i, x):
            if i == len(toppingCosts) or x <= 0: 
                return 0
            skip = dp(i+1, x)
            take = toppingCosts[i] + dp(i+1, x - toppingCosts[i])
            return min([skip, take], key=lambda y: (abs(y - x), y))

        ans = float('inf')
        for bc in baseCosts:
            cur = bc + dp(0, target - bc)
            ans = min([ans, cur], key=lambda y: (abs(y - target), y))
        return ans

