from typing import List

class Solution:
    def restoreIpAddresses(self, s: str) -> List[str]:
        res = []
        def backtrack(start: int, parts: List[str]) -> None:
            if len(parts) == 4:
                if start == len(s):
                    res.append('.'.join(parts))
                return
            remaining = 4 - len(parts)
            if len(s) - start < remaining or len(s) - start > remaining * 3:
                return
            for l in range(1, 4):
                if start + l > len(s):
                    break
                seg = s[start:start + l]
                if (seg.startswith('0') and len(seg) > 1) or int(seg) > 255:
                    continue
                parts.append(seg)
                backtrack(start + l, parts)
                parts.pop()
        backtrack(0, [])
        return res

