from functools import lru_cache
from typing import List
import math

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        @lru_cache(None)
        def rec(i: int, rem: int) -> int:
            if i == len(toppingCosts) or rem < 0:
                return 0
            # skip topping i or take it
            skip = rec(i+1, rem)
            take = toppingCosts[i] + rec(i+1, rem - toppingCosts[i]) if rem >= toppingCosts[i] else math.inf
            # choose closer to target using (abs, cost)
            return min((skip, take), key=lambda y: (abs(y - rem), y))

        INF = math.inf
        best = INF
        for bc in baseCosts:
            best = min(best, bc + rec(0, target - bc), key=lambda x: (abs(x - target), x))
        return best

def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
    inorder_map={val:idx for idx, val in enumerate(inorder)}
    preorder_idx=0

    def treeHelper(left, right):
        nonlocal preorder_idx
        if left>right:
            return None

        node_val = preorder[preorder_idx] 
        root=TreeNode(node_val)
        preorder_idx+=1

        inorder_index=inorder_map[node_val]

        root.left = treeHelper(left, inorder_index-1)
        root.right = treeHelper(inorder_index+1, right)

        return root

    return treeHelper(0, len(inorder)-1)

