class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        from functools import lru_cache

        def compress(cnt: int) -> int:
            return len(str(cnt)) + 1 if cnt > 1 else 1

        @lru_cache(None)
        def dp(i: int, prev: str, cnt: int, k_left: int) -> int:
            if k_left < 0:
                return float('inf')
            if i == len(s):
                return compress(cnt) if cnt else 0

            # delete current character
            delete = dp(i + 1, prev, cnt, k_left - 1)

            # keep current character
            if s[i] == prev:
                keep = dp(i + 1, prev, cnt + 1, k_left)
            else:
                keep = compress(cnt) + dp(i + 1, s[i], 1, k_left)

            return min(delete, keep)

        return dp(0, '', 0, k)

