class Solution:
    MOD = 10**9+7
    def numPermsDISequence(self, s: str) -> int:
        n = len(s)
        dp = [1] * (n+1)
        for i, c in enumerate(s):
            new_dp = [0] * (n-i)
            if c == 'I':
                cur = 0
                for j in range(i+1):
                    cur = (cur + dp[j]) % self.MOD
                    new_dp[j] = cur
            else:
                cur = 0
                for j in range(i, -1, -1):
                    cur = (cur + dp[j]) % self.MOD
                    new_dp[j] = cur
            dp = new_dp
        return dp[0] % self.MOD

