from typing import List

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        @lru_cache(None)
        def dfs(i, remain):
            if remain < 0 or i == len(toppingCosts):
                return 0
            use = dfs(i+1, remain)
            not_use = dfs(i+1, remain - toppingCosts[i])
            return min([use, toppingCosts[i] + not_use], key=lambda y: (abs(y - remain), y))

        best = inf
        for bc in baseCosts:
            best = min(best, bc + dfs(0, target - bc), key=lambda x: (abs(x-target), x))
        return best

