from typing import List

class Solution:
    def getAncestors(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        g = [[] for _ in range(n)]
        indeg = [0] * n
        for u, v in edges:
            g[u].append(v)
            indeg[v] += 1

        q = deque([i for i in range(n) if indeg[i] == 0])
        ans = [set() for _ in range(n)]

        while q:
            u = q.popleft()
            for v in g[u]:
                ans[v].add(u)
                ans[v].update(ans[u])
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)

        return [sorted(list(s)) for s in ans]

