            return 0
        s1 = ''.join(c for c in s1 if c in s2)
        if not s1:
            return 0
        idx = cnt = 0
        repeats = [0] * (len(s2) + 1)
        for i in range(1, n1 + 1):
            for ch in s1:
                if idx < len(s2) and ch == s2[idx]:
                    idx += 1
                    if idx == len(s2):
                        cnt += 1
                        idx = 0
            repeats[i] = cnt
        for start in range(1, len(repeats)):
            if repeats[start] == repeats[-1]:
                break
        else:
            start = len(repeats)
        cycle_len = start
        total = repeats[-1] * (n1 // start) + repeats[n1 % start]
        return total // n2

