class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        i=j=repeat=cur=0
        index={}
        while repeat<n1:
            if i==len(s1):
                repeat+=1
                i=0
            if s1[i]==s2[j]:
                j+=1
                if j==len(s2):
                    cur+=1
                    j=0
            if j==0:
                if i in index:
                    prev_repeat,prev_cur=index[i]
                    cycle_repeat=repeat-prev_repeat
                    cycle_cur=cur-prev_cur
                    rem=n1-repeat
                    cur+=rem//cycle_repeat*cycle_cur
                    repeat+=rem//cycle_repeat*cycle_repeat
                else:
                    index[i]=(repeat,cur)
            i+=1
        return cur//n2

