class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        @lru_cache(None)
        def dfs(i, nxt):
            if i == n:
                return 1
            res = 0
            if s[i] == 'I':
                for v in range(nxt+1):
                    res = (res + dfs(i+1, v)) % MOD
            else:
                for v in range(nxt-1, -1, -1):
                    res = (res + dfs(i+1, v)) % MOD
            return res
        return dfs(0, 0)

