class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        trie = {}
        for f in forbidden:
            t = trie
            for c in f:
                t = t.setdefault(c, {})
            t["#"] = True

        start = 0
        max_len = 0
        for i, ch in enumerate(word):
            t = trie
            # check substrings starting at i
            for j in range(i, len(word)):
                c = word[j]
                if c not in t:
                    break
                t = t[c]
                if "#" in t:
                    # forbidden found, move start just after its start
                    start = i + 1
                    break
            max_len = max(max_len, i - start + 1)
        return max_len

