class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        m, n = len(pizza), len(pizza[0])
        MOD = 10**9 + 7

        # prefix sum of apples
        pref = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m):
            for j in range(n):
                pref[i + 1][j + 1] = pref[i + 1][j] + pref[i][j + 1] - pref[i][j] + (pizza[i][j] == 'A')

        @lru_cache(None)
        def dfs(r1, c1, cuts):
            # need at least one apple per slice
            if cuts == 1:
                total = pref[m][n] - pref[r1][n] - pref[m][c1] + pref[r1][c1]
                return 1 if total else 0

            ans = 0
            # horizontal cuts
            for i in range(r1, m):
                if self._hasApple(pref, r1, i, c1, n - 1):
                    ans += dfs(i + 1, c1, cuts - 1)
                    ans %= MOD
            # vertical cuts
            for j in range(c1, n):
                if self._hasApple(pref, r1, m - 1, c1, j):
                    ans += dfs(r1, j + 1, cuts - 1)
                    ans %= MOD
            return ans

        total_apples = pref[m][n]
        if total_apples < k:
            return 0
        return dfs(0, 0, k - 1) % MOD

    def _hasApple(self, pref, r0, r1, c0, c1):
        return (pref[r1 + 1][c1 + 1] -
                pref[r0][c1 + 1] -
                pref[r1 + 1][c0] +
                pref[r0][c0]) > 0

