from typing import List

class Solution:
    def minimumTotalPrice(self, n: int, edges: List[List[int]], price: List[int], trips: List[List[int]]) -> int:
        g = [[] for _ in range(n)]
        for i, j in edges:
            g[i].append(j)
            g[j].append(i)

        freq = [0] * n
        level = [0] * n
        parent = [0] * n

        def dfs(i, l, p):
            level[i] = l
            parent[i] = p
            for j in g[i]:
                if j != p:
                    dfs(j, l + 1, i)

        def lca(a, b):
            if level[a] > level[b]:
                a, b = b, a
            d = level[b] - level[a]
            while d:
                b = parent[b]
                d -= 1
            if a == b:
                return a
            while a != b:
                a = parent[a]
                b = parent[b]
            return a

        dfs(0, 0, -1)
        for a, b in trips:
            l = lca(a, b)
            while a != l:
                freq[a] += 2
                a = parent[a]
            freq[l] += 1
            while b != l:
                freq[b] += 1
                b = parent[b]

        def dp(i, p):
            # dp[i][0] = max profit without discount at i, dp[i][1] = profit with discount at i
            take = price[i] // 2 * freq[i]
            notake = 0
            gain = 0
            for j in g[i]:
                if j != p:
                    child0, child1 = dp(j, i)
                    gain += max(child0, child1)
                    notake += child0
            return [gain + take, notake + take]

        total = sum(freq[i] * price[i] for i in range(n))
        return total - max(dp(0, -1)[1])

