class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        count = [0] * len(s2)
        k2, i2 = 0, 0
        start = {}
        i1 = 0
        while i1 < n1:
            for ch in s2:
                pos = s1.find(ch, i1 % len(s1))
                if pos == -1:
                    i2 = 0
                    count[i2] = 0
                    break
                i1 = (i1 % len(s1)) + pos + 1
            if i2 == len(s2):
                k2 += 1
                i2 = 0
            key = (i1 % len(s1), i2)
            if key in start:
                prev_i1, prev_k2 = start[key]
                cycle_len = i1 - prev_i1
                cycle_k2 = k2 - prev_k2
                cycles = (n1 - prev_i1) // cycle_len
                k2 = prev_k2 + cycles * cycle_k2
                i1 += cycles * cycle_len
                break
            start[key] = (i1, k2)
        return k2 // n2

