            # either skip current topping or take it
            return min(
                dfs(i + 1, rem),
                toppingCosts[i] + dfs(i + 1, rem - toppingCosts[i]),
                key=lambda v: (abs(v - target), v)
            )

        ans = float('inf')
        for bc in baseCosts:
            ans = min(ans, bc + dfs(0, target - bc), key=lambda v: (abs(v - target), v))
