    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        lst, cnt, i, j = [], 0, 0, 0
        state = {}
        while i < s1 * n1:
            if s1[i % len(s1)] == s2[j]:
                j += 1
                if j == len(s2):
                    cnt += 1
                    j = 0
            lst.append(cnt)
            key = (i % len(s1), j)
            if key in state:
                prev_i, prev_cnt = state[key]
                cycle_len = i - prev_i
                cycle_cnt = cnt - prev_cnt
                cycles = (n1 - prev_i) // cycle_len
                cnt = prev_cnt + cycles * cycle_cnt
                break
            state[key] = (i, cnt)
            i += 1
        return cnt // n2

