class Solution:
    def minimumTotalPrice(self, n: int, edges: List[List[int]], price: List[int], trips: List[List[int]]) -> int:
        g = [[] for _ in range(n)]
        for i, j in edges:
            g[i].append(j)
            g[j].append(i)
        freq = [0] * n
        level = [0] * n
        parent = [-1] * n

        def dfs(u, lev, p):
            level[u] = lev
            parent[u] = p
            for v in g[u]:
                if v != p:
                    dfs(v, lev + 1, u)

        def LCA(a, b):
            if level[a] > level[b]:
                a, b = b, a
            d = level[b] - level[a]
            while d:
                b = parent[b]
                d -= 1
            if a == b:
                return a
            while a != b:
                a = parent[a]
                b = parent[b]
            return a

        dfs(0, 0, -1)
        for u, v in trips:
            l = LCA(u, v)
            while u != l:
                freq[u] += 1
                u = parent[u]
            freq[l] += 1
            while v != l:
                freq[v] += 1
                v = parent[v]

        from functools import lru_cache

        @lru_cache(None)
        def dp(u, p):
            res0 = 0          # max total when u gets no discount
            res1 = price[u] // 2 * freq[u]   # total when u gets discount
            for v in g[u]:
                if v != p:
                    cur = dp(v, u)
                    res0 += max(cur)
                    res1 += cur[0]
            return [res1, res0]

        ans = sum(freq[i] * price[i] for i in range(n))
        return ans - dp(0, -1)[0]

