class Solution:
    def restoreIpAddresses(self, s: str) -> List[str]:
        res: List[str] = []
        cur: List[str] = []

        def backtrack(i: int) -> None:
            if i == len(s) and len(cur) == 4:
                res.append('.'.join(cur))
                return
            if len(cur) == 4 or i >= len(s):
                return
            # Handle leading zero case
            if s[i] == '0':
                cur.append('0')
                backtrack(i + 1)
                cur.pop()
                return
            # Try segments of length 1 to 3
            for length in range(1, 4):
                if i + length > len(s):
                    break
                segment = s[i:i+length]
                if length > 1 and s[i] == '0':  # disallow leading zeros
                    continue
                if int(segment) <= 255:
                    cur.append(segment)
                    backtrack(i + length)
                    cur.pop()

        backtrack(0)
        return res

