    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        ptr = 0
        occ = {}
        total = 0
        for i in range(n1):
            cnt = 0
            for ch in s2:
                pos = s1.find(ch, ptr)
                if pos == -1:
                    return total // n2
                ptr = pos + 1
                cnt += 1
            if ptr in occ:
                prev = occ[ptr]
                cycle_len = i - prev
                repeat = (n1 - i) // cycle_len
                total += repeat * cnt
                break
            occ[ptr] = i
            total += cnt
        return total // n2

