        MOD = 10**9 + 7
        if primeFactors <= 3:
            return primeFactors
        rem = primeFactors % 3
        pow3 = primeFactors // 3
        if rem == 0:
            return pow(3, pow3, MOD)
        elif rem == 1:
            return (4 * pow(3, pow3 - 1, MOD)) % MOD
        else:  # rem == 2
            return (2 * pow(3, pow3, MOD)) % MOD

