from collections import defaultdict, deque
from typing import List

class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        # build dependency graph and compute indegree for each recipe
        graph = defaultdict(list)
        indegree = defaultdict(int)
        supply_set = set(supplies)

        # count how many ingredients of each recipe are initially unavailable
        for i, recipe in enumerate(recipes):
            indegree[recipe] = 0
            for ing in ingredients[i]:
                if ing not in supply_set:
                    indegree[recipe] += 1
                # edge from ingredient (if it's a recipe) to dependent recipe
                if ing in recipes:
                    graph[ing].append(recipe)

        # start with recipes that have all ingredients available
        q = deque([r for r in recipes if indegree[r] == 0])
        result = []

        while q:
            cur = q.popleft()
            result.append(cur)
            supply_set.add(cur)          # now this recipe becomes a supply
            # reduce indegree of dependent recipes
            for nxt in graph[cur]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    q.append(nxt)

        return result

