from functools import lru_cache
from typing import List

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        self.r = len(pizza)
        self.c = len(pizza[0])
        # prefix sum of apples
        pref = [[0]*(self.c+1) for _ in range(self.r+1)]
        for i in range(self.r):
            for j in range(self.c):
                pref[i+1][j+1] = pref[i][j+1] + pref[i+1][j] - pref[i][j] + (pizza[i][j]=='A')

        @lru_cache(None)
        def apple(r1,c1,r2,c2):
            return pref[r2+1][c2+1] - pref[r1][c2+1] - pref[r2+1][c1] + pref[r1][c1]

        @lru_cache(None)
        def dfs(i,j,p):
            if p == 1:
                return 1 if apple(i,j,self.r-1,self.c-1) > 0 else 0
            ways = 0
            # horizontal cuts
            for r in range(i+1, self.r):
                if apple(i,j,r-1,self.c-1) > 0:
                    ways += dfs(r,j,p-1)
            # vertical cuts
            for c in range(j+1, self.c):
                if apple(i,j,self.r-1,c-1) > 0:
                    ways += dfs(i,c,p-1)
            return ways % 1000000007

        return dfs(0,0,k)

