class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        from functools import lru_cache

        @lru_cache(None)
        def dp(i, prev, cnt, left):
            # i: index, prev: last kept char, cnt: its run length, left: deletions left
            if i == len(s):
                # encode remaining run
                return 0 if cnt == 0 else (len(str(cnt)) + 1 if cnt > 9 else 2 if cnt > 1 else 1)
            # delete current char
            delete = dp(i+1, prev, cnt, left-1) if left else float('inf')
            # keep current char
            if s[i] == prev:
                keep = dp(i+1, prev, cnt+1, left)
            else:
                keep = (len(str(cnt)) + 1 if cnt > 9 else 2 if cnt > 1 else 1) + dp(i+1, s[i], 1, left)
            return min(delete, keep)

        return dp(0, "", 0, k)

